import json, re, os
from collections import Counter

_SOLUTION_CLIP_CHARS = 300

def extract_solution(solution_str, method="strict", clip=True):
    if clip and len(solution_str) > _SOLUTION_CLIP_CHARS:
        solution_str = solution_str[-_SOLUTION_CLIP_CHARS:]
    if method == "strict":
        solutions = re.findall(r"#### (\-?[0-9\.\,]+)", solution_str)
        if len(solutions) == 0:
            return None
        return solutions[-1].replace(",", "").replace("$", "")
    else:
        answer = re.findall(r"(\-?[0-9\.\,]+)", solution_str)
        final_answer = None
        if len(answer) == 0:
            return None
        invalid_str = ["", "."]
        for final_answer in reversed(answer):
            if final_answer not in invalid_str:
                break
        return final_answer

def norm(a):
    if a is None: return None
    return a.replace(",", "").replace("$", "")

def load(path):
    rows=[]
    with open(path) as f:
        for line in f:
            line=line.strip()
            if line:
                rows.append(json.loads(line))
    return rows

def analyze(path, label):
    rows=load(path)
    n=len(rows)
    score1=sum(1 for r in rows if r["score"]==1.0)
    # recompute
    methods={}
    # categories
    cat=Counter()
    lens=[]
    trunc=0
    has_hash=0
    last_is_hash=0
    false_pos_examples=[]
    false_neg_examples=[]
    clip_changes=0
    # numbers only in tail vs full
    for r in rows:
        out=r["output"]
        gt=str(r["gts"])
        lens.append(len(out))
        if len(out)>=2000 or out.endswith("...") or "finish" in r:
            pass
        flex_clip=norm(extract_solution(out,"flexible",True))
        flex_full=norm(extract_solution(out,"flexible",False))
        strict_clip=norm(extract_solution(out,"strict",True))
        strict_full=norm(extract_solution(out,"strict",False))
        if flex_clip!=flex_full:
            clip_changes+=1
        if "####" in out:
            has_hash+=1
        # does output end with #### answer?
        # truncation heuristic: length near max token? we don't have token count. char length high.
        logged=r["score"]
        # agreement with flex clip (should match logged if same reward)
        pred_score=1.0 if flex_clip==gt else 0.0
        if abs(pred_score-logged)>1e-6:
            cat["logged_mismatch"]+=1
        # true-ish: strict full match OR flexible full match
        strict_ok = strict_full==gt
        flex_ok = flex_full==gt
        clip_ok = flex_clip==gt
        if clip_ok and not flex_ok:
            cat["clip_false_positive"]+=1
            if len(false_pos_examples)<3:
                false_pos_examples.append((gt, flex_clip, flex_full, strict_full, out[-400:], out[:200]))
        if flex_ok and not clip_ok:
            cat["clip_false_negative"]+=1
            if len(false_neg_examples)<2:
                false_neg_examples.append((gt, flex_clip, flex_full, out[-400:]))
        if clip_ok and not strict_ok:
            cat["flex_pos_strict_neg"]+=1
        if strict_ok:
            cat["strict_correct"]+=1
        if flex_ok:
            cat["flex_full_correct"]+=1
        if clip_ok:
            cat["flex_clip_correct"]+=1
        # answer appears as last line number only
        # repetition: same sentence many times
        if out.count(out[:80])>3 and len(out)>200:
            cat["heavy_repeat_prefix"]+=1
        # ends with number equal gt
        tail=out.rstrip()[-30:]
        if re.search(r"####\s*"+re.escape(gt)+r"\s*$", out.strip()):
            cat["ends_with_hash_gt"]+=1
        # very short
