import json, re, math
from collections import Counter, defaultdict

num_re=re.compile(r"(\-?[0-9\.\,]+)")
boxed_re=re.compile(r"\\boxed\{([^{}]*)\}")

def nums(s):
    out=[]
    for m in num_re.findall(s):
        if m not in ("","."):
            out.append(m.replace(",",""))
    return out

def last_num(s):
    n=nums(s)
    return n[-1] if n else None

def load(p):
    rows=[]
    with open(p) as f:
        for line in f:
            if line.strip(): rows.append(json.loads(line))
    return rows

def prompt_text(inp):
    i=inp.find("user\n")
    text=inp[i+5:] if i>=0 else inp
    return text.split("Let's think")[0]

def qkey(inp):
    return prompt_text(inp).strip()[:300]

def rel_err(pred, gt):
    try:
        p=float(pred); g=float(gt)
    except:
        return None
    if g==0:
        return None
    return abs(p-g)/abs(g)

def categorize(path, label):
    rows=load(path)
    n=len(rows)
    wrong=[r for r in rows if r["score"]<0.5]
    c=Counter()
    off_by_one=0
    factor2=0
    factor10=0
    prompt_num=0
    intermediate=0  # pred appears in response numbers and also is a prompt number
    rels=[]
    close_10pct=0
    for r in wrong:
        gt=str(r["gts"]).replace(",","")
        pred=last_num(r["output"])
        pn=set(nums(prompt_text(r["input"])))
        if pred is None:
            c["no_num"]+=1
            continue
        if pred in pn:
            c["pred_in_prompt"]+=1
        re=rel_err(pred, gt)
        if re is not None:
            rels.append(re)
            if re<=0.1: close_10pct+=1
            if re<=0.01: c["within_1pct"]+=1
